        "Par cilvēku stand nozīmē stāvēt.",
        "Par priekšmetu stand nozīmē, ka tas atrodas stāvus vai noteiktā vietā.",
        "Svarīgi nošɒirt: stoungen = stāvēt, sëtzen = sēdēt, léien = gulēt/atrasties guếus."
